#include "exact_polynomial_detail.hpp"
#include <uvlas/core/instrumentation.hpp>
#include <uvlas/core/build_info.hpp>
#include <iostream>
#include <stdexcept>
#include <string>
#include <array>
using namespace uvlas; using namespace uvlas::structure;
template<class T>T take(core::Result<T> r){if(!r)throw std::runtime_error("Unexpected exact preparation failure");return std::move(*r);}
std::string canonical(const ExactRational& v){const auto& b=detail::ExactFactory::value(v).backend();return b.num().str(0,std::ios_base::dec)+"/"+b.denom().str(0,std::ios_base::dec);}
void emit(const char* phase,int bits,int round,const ExactPreparationInfo& info,std::uint64_t bytes,std::uint64_t observed,std::size_t terms){const auto memory=take(core::sample_process_memory(core::Operation::PrepareModel));if(!info.timing)throw std::runtime_error("Missing enabled timing");std::cout<<"{\"phase\":\""<<phase<<"\",\"input_bits\":"<<bits<<",\"round\":"<<round<<",\"preparation_ns\":"<<info.timing->elapsed_nanoseconds<<",\"owned_payload_bytes\":"<<bytes<<",\"external_payload_estimate_bytes\":"<<info.estimated_external_payload_bytes<<",\"algebraic_work_bits\":"<<info.algebraic_work_bits<<",\"planned_work_bits\":"<<info.planned_work_bits<<",\"observed_output_value_bits\":"<<observed<<",\"canonical_terms\":"<<terms<<",\"planned_raw_terms\":"<<info.planned_raw_terms<<",\"resident_bytes\":"<<memory.resident_bytes<<",\"process_lifetime_peak_bytes\":"<<memory.peak_resident_bytes<<"}\n";}
int main(){try{std::cerr<<uvlas::build_info_json()<<"\n";constexpr auto budget=std::uint64_t{128}*1024*1024;ExactLimits enabled{10000,1000,10000,100,200,16384,1000000,ExactEstimateAdmission{budget},ExactTimingMode::Enabled};auto disabled=enabled;disabled.timing=ExactTimingMode::Disabled;
for(const auto n:{32,256,2048}){detail::Integer integer=1;integer<<=n-1;integer+=1;const auto text=integer.str();core::ResourcePlan inputs{budget};const auto coeff=take(ExactRational::from_integer_pair(text,"3",disabled,inputs));const auto one=take(ExactRational::from_integer_pair("1","1",disabled,inputs));const auto minus=take(ExactRational::from_integer_pair("-1","1",disabled,inputs));const std::array ft{ExactInputTerm{{2,0},coeff},ExactInputTerm{{0,1},one},ExactInputTerm{{0,0},one}};const auto f=take(ExactChartPolynomial::make(ft,disabled,inputs));const std::array pt{ExactInputTerm{{1,0},one},ExactInputTerm{{0,1},one}};const std::array qt{ExactInputTerm{{1,0},one},ExactInputTerm{{0,1},minus}};const auto p=take(ExactChartPolynomial::make(pt,disabled,inputs)),q=take(ExactChartPolynomial::make(qt,disabled,inputs));
std::string stable;
for(int round=-1;round<3;++round){core::ResourcePlan parseplan{budget},mulplan{budget},subplan{budget};const auto parsed=take(ExactRational::from_integer_pair(text,"3",enabled,parseplan));const auto product=take(coeff.multiply(coeff,enabled,mulplan));const auto substituted=take(f.substitute(p,q,enabled,subplan));core::ResourcePlan offplan{budget};const auto off=take(f.substitute(p,q,disabled,offplan));if(off.preparation().timing)throw std::runtime_error("Disabled timing recorded");std::string words=canonical(parsed)+":"+canonical(product);std::uint64_t maxbits=0;for(std::size_t i=0;i<substituted.terms().size();++i){const auto& term=substituted.terms()[i];const auto& other=off.terms()[i];if(term.powers.first!=other.powers.first||term.powers.second!=other.powers.second||!(term.coefficient==other.coefficient))throw std::runtime_error("Timing altered exact words");words+=":"+std::to_string(term.powers.first)+","+std::to_string(term.powers.second)+","+canonical(term.coefficient);maxbits=std::max(maxbits,std::max(term.coefficient.numerator_bits(),term.coefficient.denominator_bits()));}if(round==-1)stable=words;else{if(words!=stable)throw std::runtime_error("Repeat canonical words differ");emit("parse",n,round,parsed.preparation(),parseplan.allocated_bytes(),std::max(parsed.numerator_bits(),parsed.denominator_bits()),0);emit("multiply",n,round,product.preparation(),mulplan.allocated_bytes(),std::max(product.numerator_bits(),product.denominator_bits()),0);emit("substitute",n,round,substituted.preparation(),subplan.allocated_bytes(),maxbits,substituted.terms().size());}}
}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
